# Run at the package root after installing upstream diptest 0.77-2.
# These fixtures are generated by the actual corrected C kernel and R wrappers.
stopifnot(as.character(packageVersion("diptest")) == "0.77.2")
library(diptest)
dir.create("test/data", showWarnings=FALSE)
set.seed(217)
data(statfaculty)
cases <- list(singleton=5, pair=c(8, 3), triple=c(0, 3, 1),
              constant=rep(3, 12), two_point=c(1, 1, 2, 2),
              termination_fix=cumsum(0:3), mirror_tie=c(0, 2, 3, 5, 6),
              yong_lu=c(1, rep(2, 9)), statfaculty=statfaculty,
              faithful_eruptions=datasets::faithful$eruptions, precip=as.vector(datasets::precip),
              mechler_1=c(198,198,1961,2898,3184,3687,4336,4987,5661,6530,7476,8555),
              mechler_2=c(198,1961,2898,3184,3687,4336,4987,5661,6530,7476,8555,9912),
              clustered=c(seq(-4,-3,length.out=30), seq(3,4,length.out=30)),
              uniform_grid=seq(0,1,length.out=40),
              steep_segments=c(0,1e-100,2e-100,1,1.1,2,2.5,7,8,9),
              large_offset=2^40+c(0,1,2,3,6,8,19,20,21,22),
              normal_quantiles=qnorm((seq_len(60)-0.5)/60))
for (n in c(4:10, 14:16, 19:21, 29:31, 49:51, 99:101, 199:201, 500, 1000)) {
    cases[[paste0("uniform_",n)]] <- runif(n)
    cases[[paste0("discrete_",n)]] <- sample(1:7, n, replace=TRUE)
}
for (i in 1:60) {
    n <- sample(4:150,1)
    cases[[paste0("random_",i)]] <- rnorm(n)
}
con <- file("test/data/oracle_cases.txt","w")
writeLines(as.character(length(cases)),con)
write_num <- function(x) writeLines(paste(sprintf("%.17e",x),collapse=" "),con)
write_int <- function(x) writeLines(paste(x,collapse=" "),con)
for (name in names(cases)) {
    x <- cases[[name]]
    stable_hulls <- name %in% c("statfaculty", "faithful_eruptions", "precip", "mechler_1", "mechler_2") ||
        grepl("^random_", name)
    r <- dip(x, full.result=if(stable_hulls) "all" else TRUE)
    writeLines(name,con)
    write_int(c(length(x),as.integer(stable_hulls)))
    write_num(c(r$dip,dip(x,min.is.0=TRUE),dip.test(x)$p.value))
    write_int(r$lo.hi)
    write_num(x)
    if (stable_hulls) {
        write_int(r$mn)
        write_int(r$mj)
        write_int(c(length(r$gcm),length(r$lcm),length(r$GCM),length(r$LCM)))
        write_int(r$gcm)
        write_int(r$lcm)
        write_int(r$GCM)
        write_int(r$LCM)
    }
}
close(con)
# Exact duplicate-knots averaging, interpolation, asymptotic boundary and tails.
tab <- readRDS("upstream/inst/extraData/qDiptab.rds")
nn <- as.numeric(rownames(tab))
pp <- as.numeric(colnames(tab))
pvalue <- function(d,n) {
    if (n<=3) return(1)
    if (n>=max(nn)) {i <- j <- length(nn); f <- 0} else {
        i <- findInterval(n,nn); j <- i+1; f <- (n-nn[i])/(nn[j]-nn[i])
    }
    y0 <- sqrt(nn[i])*tab[i,]
    y1 <- sqrt(nn[j])*tab[j,]
    1-approx(y0+f*(y1-y0),pp,xout=sqrt(n)*d,rule=2)$y
}
rows <- do.call(rbind,lapply(c(1:11,14:16,19:21,49:51,199:201,71999:72001,100000),function(n) {
    dips <- c(0,0.5,seq(0.001,0.25,length.out=23))
    if (as.character(n) %in% rownames(tab)) dips <- c(dips,tab[as.character(n),])
    cbind(n=n,d=dips,p=vapply(dips,pvalue,0.0,n=n))
}))
writeLines(apply(rows, 1, function(r) sprintf("%d %.17e %.17e", as.integer(r[1]), r[2], r[3])),
           "test/data/pvalue_cases.txt")
# Deterministic MC oracle with R's exact simulated sample columns retained.
x <- c(-3,-2.5,-2.2,-2,0,0.5,0.7,0.8,0.9,1)
set.seed(20261012)
uniforms <- matrix(runif(length(x)*257),nrow=length(x))
p <- mean(dip(x) <= apply(uniforms,2,dip))
con <- file("test/data/monte_carlo.txt","w")
write_int <- function(x) writeLines(paste(x,collapse=" "),con)
write_num <- function(x) writeLines(paste(sprintf("%.17e",x),collapse=" "),con)
write_int(dim(uniforms))
write_num(c(dip(x),p))
write_num(x)
for (b in seq_len(ncol(uniforms))) write_num(uniforms[,b])
close(con)
cat("Generated",length(cases),"full cases and",nrow(rows),"table cases; MC p =",p,"\n")
